INSERT INTO solutions (uuid, solution_space, name, req_customer, req_business) VALUES
    ('caabad12-cf62-4944-9765-4df37769a729', '22f7c9af-2a4b-4e5a-a695-a82530182405', 'Cake for Atakan', 
    'Since my son Leon’s 7th birthday in 2022, I have been ordering a custom-designed birthday cake each year, tailored specifically to his health requirements and personal preferences. Leon has a severe nut allergy, so all cakes must be completely free of nuts and any possible traces. He also strongly dislikes strawberries — whether fresh, flavored, or used in decorations — so they are strictly avoided.
In terms of flavor, he prefers chocolate, vanilla, and blueberries. He also has clear expectations when it comes to the cake’s appearance: the design should reflect his current interests. In recent years, he has requested themes such as Super Mario, LEGO figures, and a football (soccer) field. These were brought to life with detailed, edible decorations made from fondant or sugar paste — all allergen-free, of course.
Each cake is planned in close coordination with the bakery to ensure both safety and satisfaction. For Leon, taste and visual appeal are equally important — the cake should always be a true highlight of his birthday celebration.', 
    'The expiry date of my strawberries are soon.');
